async function setLanguage(lang) {
    if (!HEALTH_LANGUAGES.some(x => x.code === lang)) return;
    get().lang = lang;
    get().docs.forEach(d => d.summary = makeSummary(d));
    const saved = await save(true);
    toast(saved ? 'Language preference saved.' : 'Language changed for this session, but could not be saved.');
    route()
}

function get() { return users[active] || { id: active, name: 'Health profile', email: '', relationship: 'Self', ...fresh() } }
const processFiles = makeUploader({
    api,
    getProfile: id => users[id],
    getActive: () => active,
    toast,
    onRecord: (id) => { visitPrepData = null; if (id === active && view === 'Documents') route() },
    onFinish: id => {
        if (active === id) {
            view = 'Documents';
            route()
        }
    }
});

function api(path, options = {}) { return fetch(path, { credentials: 'same-origin', ...options, headers: {...(options.body instanceof FormData ? {} : { 'Content-Type': 'application/json' }), ...(options.headers || {}) } }).then(async r => { let contentType = r.headers.get('content-type'); let d = contentType && contentType.includes('json') ? await r.json() : null; if (!r.ok) { if (path === '/api/me' && r.status === 404) throw new Error('Wrong preview server: this page is not using the project API proxy. Stop Live Server or the HTML preview, run â€œnpm run devâ€ in this project, then open http://localhost:5274.'); throw new Error(d && d.error || `Request failed (${r.status})`) } return d }).catch(e => { if (e instanceof TypeError) throw new Error('Cannot reach the app server. Run â€œnpm run devâ€ in this project and open http://localhost:5274.'); throw e }) }

function save(immediate = false) {
    const u = get();
    if (!authState || !authState.authenticated || !u.id) return;
    const id = u.id,
        payload = { name: u.name, relationship: u.relationship || 'Family member', abha: u.abha || '', lang: u.lang || 'en', allowExternalAI: !!u.allowExternalAI, meds: u.meds || [], reminders: u.reminders || [], allergies: u.allergies || [], chronicConditions: u.chronicConditions || [], maternal: u.maternal || { appointments: [] }, doseLogs: u.doseLogs || [], messages: (u.messages || []).slice(-80) };
    const persist = () => api(`/api/profiles/${id}/workspace`, { method: 'PUT', body: JSON.stringify(payload) }).then(() => true).catch(e => {
        console.error(e);
        toast(`Save failed: ${e.message}`);
        return false
    });
    clearTimeout(saveTimers.get(id));
    if (immediate) {
        saveTimers.delete(id);
        return persist()
    }
    saveTimers.set(id, setTimeout(persist, 350))
}

function docs() { return get().docs.sort((a, b) => new Date(b.date) - new Date(a.date)) }
const today = () => new Date().toISOString().slice(0, 10);
const fmt = d => {
    const value = String(d == null ? '' : d);
    const date = /^\d{4}-\d{2}-\d{2}$/.test(value) ? new Date(value + 'T12:00:00') : new Date(value);
    return Number.isNaN(date.getTime()) ? 'Date not recorded' : date.toLocaleDateString(undefined, { month: 'short', day: 'numeric', year: 'numeric' });
};

function toast(t, undo) {
    let x = $('.toast');
    if (x) x.remove();
    x = document.createElement('div');
    x.className = 'toast';
    const msg = document.createElement('span');
    msg.textContent = t;
    x.append(msg);
    if (undo) {
        const b = document.createElement('button');
        b.className = 'toast-undo';
        b.textContent = 'Undo';
        b.onclick = () => {
            clearTimeout(toastTimer);
            x.remove();
            undo()
        };
        x.append(b)
    }
    document.body.append(x);
    clearTimeout(toastTimer);
    toastTimer = setTimeout(() => x.remove(), undo ? 8000 : 2800)
}

