function shell(content) { let u = get(); return `<div class="shell"><aside class="sidebar"><div class="brand"><div class="brandmark">${icon('logo')}</div><span class="brandname">health<span style="color:#3c805e">copilot</span></span></div><div class="navlabel">YOUR HEALTH</div><nav class="nav">${navData.slice(0,6).map(x=>navItem(...x)).join('')}</nav><div class="navgap"></div><div class="navlabel">MANAGE</div><nav class="nav">${navData.slice(6).map(x=>navItem(...x)).join('')}</nav><div class="sidebottom"><div class="privacy-mini"><b>${icon('shield')} Encrypted health data</b>Stored in your private account.</div><div class="userbox"><div class="avatar">${esc((u.name||'U').split(' ').map(x=>x[0]).join('').slice(0,2))}</div><div class="usertext"><b>${esc(u.name)}</b><span>${esc(u.email||'Google account')}</span></div></div></div></aside><main class="main"><header class="topbar"><div class="crumb">Health workspace&nbsp; / &nbsp;<strong>${view}</strong></div><div class="topright"><select class="select language-select" id="globalLangSelect" aria-label="Language preference">${languageOptions(u.lang||'en')}</select><span class="badge"><i class="green-dot"></i> Secure account</span><div class="profile-selector"><select class="select" id="switchProfile" aria-label="Switch health profile">${Object.entries(users).map(([id,v])=>`<option value="${esc(id)}" ${id===active?'selected':''}>${esc(v.name||id)}</option>`).join('')}</select></div><button class="button small" data-action="logout">Sign out</button></div></header><section class="page">${content}</section></main></div>`}
function head(title,sub,action=''){return `<div class="pagehead"><div><div class="eyebrow">Your personal health workspace</div><h1>${title}</h1><div class="subhead">${sub}</div></div>${action}</div>`}
function metric(label,val,note,ico){return `<div class="metric"><div class="metric-top">${label}<div class="metric-icon">${icon(ico)}</div></div><div class="metric-val">${val}</div><div class="metric-note">${note}</div></div>`}
function docCard(d){return `<div class="docrow"><div class="docicon">${icon(d.type==='Lab report'?'chart':'file')}</div><div class="docbody"><b>${esc(d.title)}</b><span>${fmt(d.date)} Â· ${esc(d.type)} Â· ${d.values?.length||0} values extracted</span></div>${d.values?.some(v=>v.abnormal)?'<span class="tag warn">Review values</span>':'<span class="tag">Processed</span>'}<div class="doc-actions"><button class="button small" data-action="viewdoc" data-id="${d.id}">View</button><button class="button small" data-action="deldoc" data-id="${d.id}">Delete</button></div></div>`}
function recentList(ds){return ds.length?ds.slice(0,4).map(d=>`<div class="timeline-item"><div class="docicon">${icon('file')}</div><div class="docbody"><b>${esc(d.title)}</b><span>${fmt(d.date)} Â· ${esc(d.type)}</span></div>${d.values?.some(v=>v.abnormal)?'<span class="tag warn">Review</span>':''}</div>`).join(''):`<div class="empty"><div class="metric-icon">${icon('file')}</div>No records yet. Upload a medical document.</div>`}
function dashboard(){const u=get(),ds=docs(),labs=allLabs(),ab=ds.reduce((n,d)=>n+(d.values?.some(v=>v.abnormal)||0),0),meds=[...new Set([...ds.flatMap(d=>d.medicines||[]).map(m=>m.name),...(u.meds||[]).map(m=>m.name)])];return `${head(`Good ${timeWord()}, ${esc(u.name.split(' ')[0])}.`,'A clearer picture of your health starts here.')}<div class="welcome"><div class="welcome-text"><h2>Your health, all in one place.</h2><p>Upload a record to turn it into a clear, easy-to-understand summary.</p></div><button class="button" data-action="upload">${icon('upload')} Add a health record</button></div><div class="metrics">${metric('Health records',ds.length,'Across your timeline','file')}${metric('Current medicines',meds.length,meds.length?'From uploaded documents':'No medicines identified','heart')}${metric('Lab values',labs.length,'Extracted results','chart')}${metric('Needs a closer look',ab,ab?'Check with your clinician':'No flagged values','alert')}</div><div class="dashboard-grid"><div><div class="card"><div class="cardhead"><div><div class="cardtitle">Recent health activity</div><div class="cardhint">Your latest records, in one timeline</div></div><button class="text-button" data-view="Documents">View all â†’</button></div>${recentList(ds)}</div><div class="card"><div class="cardhead"><div><div class="cardtitle">Health trends</div><div class="cardhint">Changes over time from your uploaded labs</div></div><button class="text-button" data-view="Trends">View trends â†’</button></div>${miniChart()}</div></div><div><div class="card"><div class="cardhead"><div><div class="cardtitle">Latest lab results</div><div class="cardhint">Reference ranges depend on your lab</div></div></div>${labs.length?labs.slice(0,4).map(l=>`<div class="timeline-item"><div class="docbody"><b>${esc(l.name)}</b><span>${esc(l.value)} ${esc(l.unit||'')} Â· ${fmt(l.date)}</span></div><span class="tag ${l.abnormal?'warn':''}">${l.abnormal?'Review':'In range'}</span></div>`).join(''):'<div class="empty">Your results will appear after you add a lab report.</div>'}</div><div class="card"><div class="cardtitle" style="margin-bottom:12px">Your health assistant</div><div class="insight"><b>Get ready for an appointment</b><p>Build a list of questions based on your records and flagged results.</p></div><button class="button small" data-view="Doctor Visit Prep">Prepare for a visit â†’</button></div><div class="advisory">${icon('shield')} HealthCopilot helps organize information; it does not diagnose, treat, or replace a clinician.</div></div></div>`}
function timeWord(){let h=new Date().getHours();return h<12?'morning':h<18?'afternoon':'evening'}
function documentsPage(){let ds=docs().filter(d=>(typeFilter==='all'||d.type===typeFilter)&&(!filter||(`${d.title} ${d.type} ${d.summary} ${d.raw}`.toLowerCase().includes(filter.toLowerCase())))&&(dateFilter==='all'||Date.now()-new Date(d.date).getTime()<Number(dateFilter)*86400000));return `${head('Your health records','A private, searchable history of your medical documents.',`<button class="button primary" data-action="upload">${icon('plus')} Upload record</button>`)}<div class="card"><div class="filters"><input class="field search" id="searchDocs" placeholder="Search records, conditions, resultsâ€¦" value="${esc(filter)}"> <select class="select" id="typeFilter"><option value="all">All document types</option>${['Prescription','Lab report','Discharge summary','Diagnostic report','Other'].map(t=>`<option ${t===typeFilter?'selected':''}>${t}</option>`).join('')}</select><select class="select" id="dateFilter"><option value="all">Any time</option><option value="30" ${dateFilter==='30'?'selected':''}>Past 30 days</option><option value="180" ${dateFilter==='180'?'selected':''}>Past 6 months</option><option value="365" ${dateFilter==='365'?'selected':''}>Past year</option></select></div>${ds.length?ds.map(docCard).join(''):'<div class="empty">No records match. Try another filter or upload a medical document.</div>'}</div><div class="advisory">${icon('shield')} Uploaded files and extracted data are encrypted in your account database. Verify all extracted details against the original.</div>`}
function allLabs(){return docs().flatMap(d=>(d.values||[]).map(v=>({...v,date:d.date,docId:d.id})))}
function miniChart(){const labs=allLabs(),sugar=labs.filter(l=>/glucose|sugar|hba1c/i.test(l.name));return `<div class="chart-wrap">${chartSvg(sugar.slice(-8))}</div>`}
function chartSvg(points){if(!points.length)return `<div class="empty" style="padding-top:55px">Add multiple lab reports to see trends here.</div>`;const plotted=points.map(point=>({point,value:Number.parseFloat(point.value)})).filter(item=>Number.isFinite(item.value));if(!plotted.length)return '<div class="empty">No numeric results to chart.</div>';let vals=plotted.map(x=>x.value),lo=Math.min(...vals),hi=Math.max(...vals),pad=(hi-lo||hi*.1||1)*.2;lo=Math.max(0,lo-pad);hi+=pad;let w=650,h=180,left=48,right=12,top=12,bottom=30, x=i=>left+i*(w-left-right)/Math.max(1,vals.length-1),y=v=>top+(hi-v)*(h-top-bottom)/(hi-lo||1);let path=vals.map((v,i)=>`${i?'L':'M'}${x(i)},${y(v)}`).join(' ');return `<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="Health result trend chart"><line class="chart-grid" x1="${left}" x2="${w-right}" y1="${top+12}" y2="${top+12}"/><line class="chart-grid" x1="${left}" x2="${w-right}" y1="${h-bottom}" y2="${h-bottom}"/><text class="chart-text" x="1" y="${top+15}">${esc(hi.toFixed(1))}</text><text class="chart-text" x="1" y="${h-bottom}">${esc(lo.toFixed(1))}</text><path class="chart-line" d="${path}"/>${plotted.map(({point},i)=>`<circle class="chart-dot" cx="${x(i)}" cy="${y(vals[i])}" r="4"><title>${esc(point.name)}: ${esc(point.value)} ${esc(point.unit||'')} â€” ${fmt(point.date)}</title></circle><text class="chart-text" text-anchor="middle" x="${x(i)}" y="${h-7}">${esc(fmt(point.date).split(',')[0])}</text>`).join('')}</svg>`}
function trendsPage(){const labs=allLabs();return `${head('Your health trends','Compare recurring lab values across your reports. Hover over a point for exact results.')}${renderTrends({labs,selected:window.chartKey,range:trendRange,fmt,chartSvg})}`}
function profilePage(){let u=get(),meds=[...new Map([...docs().flatMap(d=>d.medicines||[]),...(u.meds||[])].map(m=>[m.name,m])).values()],dx=[...new Set(docs().flatMap(d=>d.diagnoses||[]))];return `${head('Health profile','A unified view of your health information and what has been extracted.')}<div class="dashboard-grid"><div><div class="card"><div class="cardhead"><div class="cardtitle">Personal information</div><button class="button small" data-action="editprofile">Edit profile</button></div><div class="profilecard"><div class="avatar">${esc((u.name||'U').split(' ').map(x=>x[0]).join('').slice(0,2))}</div><div><b>${esc(u.name)}</b><span>${esc(u.email||'Demo workspace Â· local only')}</span></div></div><div class="settingrow">ABHA link <span>${u.abha?'Linked Â· '+esc(u.abha):'Not connected'}</span></div><div class="settingrow">Records in profile <span>${docs().length} documents</span></div></div><div class="card"><div class="cardtitle">Diagnoses and conditions</div>${dx.length?dx.map(x=>`<div class="timeline-item"><div class="docbody"><b>${esc(x)}</b></div></div>`).join(''):'<div class="empty">No diagnoses identified in your uploaded reports.</div>'}</div><div class="card"><div class="cardtitle">Allergies and conditions</div>${(dx.length||u.chronicConditions?.length)?[...dx,...(u.chronicConditions||[])].map(x=>`<div class="timeline-item"><div class="docbody"><b>${esc(x)}</b><span>Recorded profile information</span></div></div>`).join(''):'<div class="empty">No conditions recorded.</div>'}${(u.allergies||[]).length?(u.allergies||[]).map(x=>`<div class="timeline-item"><div class="docbody"><b>${esc(x)}</b><span>Recorded allergy</span></div></div>`).join(''):'<div class="empty">No allergies recorded. Add only confirmed allergies.</div>'}<button class="button small" data-action="editclinical">Edit conditions and allergies</button></div></div><div><div class="card"><div class="cardhead"><div class="cardtitle">Current medicines</div><button class="button small" data-action="addmed">${icon('plus')} Add</button></div>${meds.length?meds.map(m=>`<div class="timeline-item"><div class="docbody"><b>${esc(m.name)}</b><span>${esc(m.dosage||'Dosage not specified')} Â· from uploaded record</span></div></div>`).join(''):'<div class="empty">No medicines identified. Add one or upload a prescription.</div>'}</div><div class="card"><div class="cardtitle" style="margin-bottom:12px">Latest lab results</div>${allLabs().slice(0,5).map(l=>`<div class="timeline-item"><div class="docbody"><b>${esc(l.name)}</b><span>${esc(l.value)} ${esc(l.unit||'')} Â· ${fmt(l.date)}</span></div><span class="tag ${l.abnormal?'warn':''}">${l.abnormal?'Review':'Recorded'}</span></div>`).join('')||'<div class="empty">No lab values recorded.</div>'}</div></div></div><div class="advisory">${icon('shield')} This is an automatically compiled record. Confirm all details with your healthcare professional.</div>`}
