function maternalCarePage(){return `${head('Maternal care','Optional pregnancy timeline, appointment notes, and trusted care links.')}${renderMaternalCare(get().maternal||{},get().lang||'en')}`}
function familyPage(){return `${head('Family profiles','Create separate demo profiles for the people whose records you help manage.',`<button class="button primary" data-action="addfamily">${icon('plus')} Add profile</button>`)}<div class="card">${Object.entries(users).map(([id,u])=>`<div class="profilecard"><div class="avatar">${esc((u.name||'U').split(' ').map(x=>x[0]).join('').slice(0,2))}</div><div><b>${esc(u.name)} ${id===active?'<span class="tag">Active</span>':''}</b><span>${esc(u.email||'Local demo profile')} Â· ${u.docs.length} records</span></div><button class="button small" data-action="switch" data-id="${esc(id)}">${id===active?'Current':'Switch'}</button>${id==='self'?'<span class="tag">Primary</span>':`<button class="delete-btn" data-action="delfamily" data-id="${esc(id)}">Remove</button>`}</div>`).join('')}</div><div class="advisory">${icon('alert')} Profiles are separated in local browser storage for this demo. Real family accounts require authenticated access controls and server-side isolation.</div>`}
function prepPage(){const current=visitPrepData?.profileId===active?visitPrepData:null;return `${head('Prepare for your visit','Build a thoughtful, profile-specific checklist for your conversation with your clinician.')}${renderVisitPrep(current,get().lang)}`}
function settingsPage(){let u=get();return `${head('Settings','Manage your language, AI data-sharing consent, and health-data export.')}<div class="card"><div class="cardtitle">Preferences</div><div class="settingrow"><div>Summary language<span style="display:block;margin-top:3px">Your language preference applies to summaries, Health Agent replies, voice input, and read-aloud.</span></div><select id="langSelect" class="select">${languageOptions(u.lang||'en')}</select></div><div class="settingrow"><div>AI health agent<span style="display:block;margin-top:3px">Allow Gemini to analyze this profile's uploaded records and answer questions. Off by default.</span></div><input id="allowExternalAI" type="checkbox" ${u.allowExternalAI?'checked':''} aria-label="Allow external AI processing"></div><div class="advisory">${icon('alert')} When enabled, your questions, recent chat, voice audio, extracted health details, and uploaded PDF/images may be sent to Google Gemini. Audio is not stored by this app. Googleâ€™s Gemini free tier says submitted content may be used to improve Google products. Do not enable free-tier AI for real patient records. Turn this on only if you consent.</div><div class="settingrow"><div>ABHA demo link<span style="display:block;margin-top:3px">Stores a clearly marked mock identifier. This is not an official ABDM connection.</span></div><button class="button small" data-action="abha">${u.abha?'Manage mock link':'Link mock ABHA ID'}</button></div><div class="settingrow"><div>Export profile data<span style="display:block;margin-top:3px">Download FHIR-style JSON for this profile.</span></div><button class="button small" data-action="fhir">${icon('download')} Export FHIR JSON</button></div><div class="settingrow"><div>Account</div><span>${esc(u.email||'Google account')}</span></div></div><div class="card"><div class="cardtitle">Delete this profile</div><div class="cardhint" style="margin:5px 0 13px">Deleting a family profile permanently deletes its records from the database.</div>${u.relationship==='Self'?'<span class="cardhint">Remove individual records from their record cards.</span>':'<button class="button" style="color:#a7504b" data-action="delfamily" data-id="'+esc(active)+'">Delete profile and records</button>'}</div><div class="advisory">${icon('shield')} Files and extracted health data are encrypted in the server database and access is checked against your Google account on each request.</div>`}
function agentPage(){let u=get();let msgs=u.messages||[];return `${head('Health Agent','Ask about your records or general health information. With AI enabled, replies use your selected language.',`<button class="button" data-action="mic">${icon('mic')} Talk to HealthCopilot</button>`)}<div class="dashboard-grid"><div class="card"><div class="cardhead"><div><div class="cardtitle">Chat with HealthCopilot</div><div class="cardhint">Try Show my sugar reports or What was my highest BP?</div><button class="button small" data-action="clearchat">Clear chat</button></div>${!u.allowExternalAI?'<div class="advisory" style="margin-bottom:12px">AI is off for this profile. Enable it in Settings to ask general health questions and receive multilingual answers. <button class="button small" data-view="Settings">Open Settings</button></div>':''}<div class="chatbox" id="chatbox">${msgs.map(m=>`<div class="bubble ${m.role==='user'?'me':'ai'}">${esc(chatPlainText(m.text))}${m.role!=='user'?`<button class="text-button" data-action="tts" data-text="${esc(chatPlainText(m.text))}">${icon('volume')} Play answer</button>`:''}</div>`).join('')||`<div class="bubble ai">${agentGreeting(esc(u.name.split(' ')[0]),get().lang)}<div class="cardhint" style="margin-top:8px">I can explain general health information and summarize what your records say. I cannot diagnose or prescribe treatment.</div></div>`}</div><form class="chatform" id="chatform"><input class="field" id="chatinput" placeholder="Ask about records or general health information?" autocomplete="off"><button class="button" type="button" data-action="mic" aria-label="Speak question">${icon('mic')}</button><button class="button primary" type="submit">Ask</button></form></div><div><div class="card"><div class="cardtitle">Suggested questions</div>${agentQuestions(get().lang).map(q=>`<button class="button small" style="margin:5px 5px 0 0" data-action="ask" data-q="${esc(q)}">${esc(q)}</button>`).join('')}</div><div class="advisory">${icon('alert')} AI can use general health information and this profile facts when enabled. Answers may be incomplete; verify records with your clinician.</div></div></div>`}
function route(){if((previousRoute.view!==view||previousRoute.profile!==active||view==='Doctor Visit Prep')&&window.speechSynthesis)window.speechSynthesis.cancel();if(previousRoute.view!==view||previousRoute.profile!==active){if(voiceAudio){voiceAudio.pause();voiceAudio.currentTime=0}document.querySelector('#universalVoiceControls')?.remove()}previousRoute={view,profile:active};const pages={Dashboard:dashboard,Documents:documentsPage,Trends:trendsPage,'Health Profile':profilePage,'Health Agent':agentPage,Reminders:remindersPage,'Maternal Care':maternalCarePage,'Family Profiles':familyPage,'Doctor Visit Prep':prepPage,Settings:settingsPage};$('#app').innerHTML=shell((pages[view]||dashboard)());localizeTree($('#app'),get().lang);bind();if(view==='Doctor Visit Prep'&&(!visitPrepData||visitPrepData.profileId!==active)&&visitPrepLoading!==active)loadVisitPrep(active);if(view==='Reminders'&&(!remindersData||remindersData.profileId!==active)&&remindersLoading!==active)loadReminders(active);if(view==='Reminders'&&pushStatusProfile!==active)loadPushStatus(active)}
async function loadReminders(profileId){remindersLoading=profileId;try{const result=await api(`/api/profiles/${profileId}/reminders`);if(active!==profileId)return;remindersData={profileId,reminders:result.reminders};remindersLoading='';route()}catch(e){if(active===profileId){remindersData={profileId,reminders:[]};remindersLoading='';toast(`Reminders could not load: ${e.message}`);route()}}}
async function loadPushStatus(profileId){pushStatusProfile=profileId;pushEnabled=await pushStatus(profileId,api);if(active===profileId&&view==='Reminders')route()}
async function loadVisitPrep(profileId){visitPrepLoading=profileId;try{const loaded=await api(`/api/visit-prep/${profileId}`);if(active!==profileId)return;visitPrepData={profileId,...loaded,language:loaded.context.language==='hi'?'hi':'en'};route();if((!loaded.questions.length||loaded.session.sourceFingerprint!==loaded.context.fingerprint||loaded.session.generatedLanguage!==visitPrepData.language)){const generated=await api('/api/visit-prep/generate',{method:'POST',body:JSON.stringify({profileId,language:visitPrepData.language,regenerate:false})});if(active===profileId){visitPrepData.questions=generated.questions;route()}}}catch(error){if(active===profileId){visitPrepData=null;toast(`Visit preparation could not load: ${error.message}`)}}finally{if(visitPrepLoading===profileId)visitPrepLoading=''}}
function bind(){document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;route()});$('#switchProfile')?.addEventListener('change',e=>{speechSynthesis?.cancel?.();voiceAudio?.pause();active=e.target.value;sessionStorage.setItem('hc_active',active);route()});$('#searchDocs')?.addEventListener('input',e=>{filter=e.target.value;let at=e.target.selectionStart;route();let inp=$('#searchDocs');inp?.focus();inp?.setSelectionRange(at,at)});$('#typeFilter')?.addEventListener('change',e=>{typeFilter=e.target.value;route()});$('#dateFilter')?.addEventListener('change',e=>{dateFilter=e.target.value;route()});$('#chartKey')?.addEventListener('change',e=>{window.chartKey=e.target.value;route()});$('#trendRange')?.addEventListener('change',e=>{trendRange=e.target.value;route()});$('#langSelect')?.addEventListener('change',e=>setLanguage(e.target.value));$('#globalLangSelect')?.addEventListener('change',e=>setLanguage(e.target.value));$('#allowExternalAI')?.addEventListener('change',e=>{get().allowExternalAI=e.target.checked;save();toast(e.target.checked?'AI provider access enabled for this profile.':'AI provider access disabled.')});$('#chatform')?.addEventListener('submit',e=>{e.preventDefault();ask($('#chatinput').value)});document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action,b));let zone=$('.uploadzone');if(zone){zone.ondragover=e=>{e.preventDefault();zone.classList.add('drag')};zone.ondragleave=()=>zone.classList.remove('drag');zone.ondrop=e=>{e.preventDefault();zone.classList.remove('drag');processFiles([...e.dataTransfer.files],$('#uploadType')?.value||'Other')}}if(view==='Reminders'&&remindersData?.profileId===active){bindReminders($('.reminders-surface'),{profileId:active,pushEnabled,api,toast,onPushEnabled:value=>{pushEnabled=value;pushStatusProfile=active;route()},onDelete:id=>{remindersData={profileId:active,reminders:remindersData.reminders.filter(r=>r.id!==id)};route()}})}if(view==='Doctor Visit Prep'&&visitPrepData?.profileId===active){bindVisitPrep($('.prep-layout'),{data:visitPrepData,profileId:active,api,toast,onUpload:uploadModal,onOpenDocument:showDoc,onData:(next,render=true)=>{visitPrepData=next;if(render&&view==='Doctor Visit Prep')route()}})}}
function modal(title,subtitle,body,submit='Save',onSave=()=>{}){const wrap=document.createElement('div');wrap.className='modal-back';wrap.innerHTML=`<div class="modal"><h2>${title}</h2><p>${subtitle}</p>${body}<div class="modalfoot"><button class="button" data-cancel>Cancel</button><button class="button primary" data-save>${submit}</button></div></div>`;document.body.append(wrap);wrap.onclick=e=>{if(e.target===wrap||e.target.closest('[data-cancel]'))wrap.remove()};wrap.querySelector('[data-save]').onclick=()=>{if(onSave(wrap)!==false)wrap.remove()};return wrap}
function action(a,b){if(a==='upload')return uploadModal();if(a==='speak')return speak(b.dataset.text||'');if(a==='tts')return speakAnswer(b.dataset.text||'',b);if(a==='addfamily')return addFamily();if(a==='switch'){active=b.dataset.id;sessionStorage.setItem('hc_active',active);route();return}if(a==='delfamily'){if(confirm('Remove this profile and permanently delete its health records?'))api(`/api/profiles/${b.dataset.id}`,{method:'DELETE'}).then(()=>{delete users[b.dataset.id];if(active===b.dataset.id){active=Object.keys(users)[0];sessionStorage.setItem('hc_active',active)}route();toast('Profile and its records deleted')}).catch(e=>toast(e.message));return}if(a==='logout'){api('/auth/logout',{method:'POST'}).finally(()=>{authState={authenticated:false,googleConfigured:!!authState?.googleConfigured};users={};sessionStorage.removeItem('hc_active');route()});return}if(a==='addreminder')return addReminder();if(a==='delreminder'){api(`/api/profiles/${active}/reminders/${b.dataset.id}`,{method:'DELETE'}).then(()=>{remindersData={profileId:active,reminders:(remindersData?.reminders||[]).filter(x=>x.id!==b.dataset.id)};route();toast('Reminder removed')}).catch(e=>toast(`Reminder could not be removed: ${e.message}`));return}if(a==='addmed')return addMed();if(a==='interaction')return interaction();if(a==='editprofile')return editProfile();if(a==='editclinical')return editClinicalContext();if(a==='abha')return abhaModal();if(a==='fhir')return exportFhir();if(a==='clearprofile'){toast('Delete records from the Documents page, or remove this family profile.');return}if(a==='print'){window.print();return}if(a==='mic')return voiceInput();if(a==='readpage')return speak($('.modal')?.innerText||$('.page')?.innerText||'');if(a==='stopread'){window.speechSynthesis?.cancel();return}if(a==='ask')return ask(b.dataset.q);if(a==='clearchat'){get().messages=[];save();route();return}if(a==='deldoc'){if(confirm('Permanently delete this health record and uploaded file?'))api(`/api/profiles/${active}/documents/${b.dataset.id}`,{method:'DELETE'}).then(()=>{get().docs=get().docs.filter(d=>d.id!==b.dataset.id);visitPrepData=null;route();toast('Health record deleted')}).catch(e=>toast(e.message));return}if(a==='viewdoc')return showDoc(b.dataset.id)}
function uploadModal(){let m=modal('Upload a health record','Files are stored encrypted on your server. If Gemini AI consent is enabled in Settings, the uploaded file may also be sent to Google for extraction. Do not upload real patient records through the free-tier AI service.','<div class="uploadzone" id="dropzone">'+icon('upload')+'<b>Drop a file here, or choose a file</b><p>PDF, JPG, PNG, WebP, TXT or CSV Â· max 12 MB</p><label class="button small">Choose file<input id="fileinput" type="file" accept=".pdf,.png,.jpg,.jpeg,.webp,.txt,.csv" multiple hidden></label></div><div class="formrow" style="margin-top:13px"><label>Document type</label><select class="select" id="uploadType">'+['Other','Prescription','Lab report','Discharge summary','Diagnostic report'].map(x=>`<option>${x}</option>`).join('')+'</select></div><button class="button small" data-manual>Enter details manually</button><div class="advisory" style="margin-top:12px">'+icon('alert')+' Verify OCR results against the original. AI summaries are informational and do not replace medical advice.</div>', 'Upload',w=>{let fi=w.querySelector('#fileinput');if(fi.files.length){processFiles([...fi.files],w.querySelector('#uploadType').value);return true}toast('Choose a PDF, image, TXT, or CSV record.');return false});let fi=m.querySelector('#fileinput');fi.onchange=()=>{if(fi.files.length){processFiles([...fi.files],m.querySelector('#uploadType').value);m.remove()}};m.querySelector('[data-manual]').onclick=()=>{m.remove();manualDoc()};let z=m.querySelector('#dropzone');z.ondragover=e=>{e.preventDefault();z.classList.add('drag')};z.ondragleave=()=>z.classList.remove('drag');z.ondrop=e=>{e.preventDefault();processFiles([...e.dataTransfer.files],m.querySelector('#uploadType').value);m.remove()};}
function manualDoc(){modal('Enter report details','Create a record from details you have checked against the original document.','<div class="grid2"><div class="formrow"><label>Document title</label><input class="field" id="manTitle" placeholder="e.g. Blood test results"></div><div class="formrow"><label>Document type</label><select class="select" id="manType">'+['Lab report','Prescription','Discharge summary','Diagnostic report','Other'].map(x=>`<option>${x}</option>`).join('')+'</select></div></div><div class="formrow"><label>Document date</label><input class="field" id="manDate" type="date" value="'+today()+'"></div><div class="formrow"><label>Report text or results</label><textarea class="field" id="manText" placeholder="Example: Glucose 98 mg/dL (70-99)"></textarea></div><div class="advisory">'+icon('alert')+' Health details are encrypted on the server. Check all entered information against the original.</div>','Save record',w=>{let title=w.querySelector('#manTitle').value.trim(),text=w.querySelector('#manText').value.trim();if(!title||!text){toast('Add a title and report text');return false}api(`/api/profiles/${active}/documents/manual`,{method:'POST',body:JSON.stringify({title,text,type:w.querySelector('#manType').value,date:w.querySelector('#manDate').value||today()})}).then(r=>{get().docs.unshift(r.document);visitPrepData=null;view='Documents';route();toast('Health record saved')}).catch(e=>toast(e.message));return true})}
function parseValues(text){const vals=[];let lines=text.split(/\n|(?<=\.|;)/);for(const line of lines){let m=line.match(/([A-Za-z][A-Za-z0-9 ()/%-]{1,35}?)\s*[:=]?\s*(-?\d+(?:\.\d+)?)\s*(mg\s*\/\s*dL|g\s*\/\s*dL|mmol\s*\/\s*L|mmHg|%|kg|cm|IU\s*\/\s*L|U\s*\/\s*L|mIU\s*\/\s*L|mg\s*\/\s*L)?\s*(?:\(\s*(?:ref(?:erence)?\s*:?\s*)?(-?\d+(?:\.\d+)?\s*(?:-|â€“|to|<|>)\s*-?\d+(?:\.\d+)?|<\s*\d+(?:\.\d+)?|>\s*\d+(?:\.\d+)?)\s*\))?/i);if(!m)continue;let name=m[1].trim().replace(/\s+/g,' ');if(!/(glucose|sugar|hba1c|a1c|cholesterol|hemoglobin|haemoglobin|creatinine|triglyceride|hdl|ldl|platelet|systolic|diastolic|blood pressure|weight|bmi|tsh|vitamin|wbc|rbc|urea|sodium|potassium|crp|bilirubin)/i.test(name))continue;let range=m[4]||'',num=Number(m[2]),abnormal=!!(range&&((range.includes('<')&&num>=Number(range.replace(/[<\s]/g,'')))||(range.includes('>')&&num<=Number(range.replace(/[>\s]/g,'')))||(/\d.*(?:-|â€“|to).*\d/.test(range)&&(()=>{let ns=range.match(/-?\d+(?:\.\d+)?/g).map(Number);return num<ns[0]||num>ns[1]})()))||/\b(H|HIGH|LOW|L|abnormal)\b/i.test(line));if(vals.some(x=>x.name.toLowerCase()===name.toLowerCase()))continue;vals.push({name,value:m[2],unit:(m[3]||'').replace(/\s/g,''),range,abnormal})}return vals}
function parseDoc(text,name,type){let dateMatch=text.match(/(?:date|collected|report date|visit date)\s*[:\-]?\s*(\d{1,2}[\/.-]\d{1,2}[\/.-]\d{2,4}|\d{4}-\d{2}-\d{2})/i),dt=today();if(dateMatch){let q=dateMatch[1];if(/^\d{4}/.test(q))dt=q.replace(/[/.]/g,'-');else{let [d,m,y]=q.split(/[\/.-]/).map(Number);if(y<100)y+=2000;dt=`${y}-${String(m).padStart(2,'0')}-${String(d).padStart(2,'0')}`}}let typePick=type||(/prescri|medicine|rx\b/i.test(text+' '+name)?'Prescription':/discharge|summary/i.test(text+' '+name)?'Discharge summary':/lab|glucose|cholesterol|hemoglobin/i.test(text+' '+name)?'Lab report':/diagnos|scan|x-ray|imaging/i.test(text+' '+name)?'Diagnostic report':'Other');let medicines=[];for(let l of text.split('\n'))if(/\b(mg|mcg|ml|tablet|capsule|once daily|twice daily)\b/i.test(l)&&/(take|tab|cap|\d+\s*(mg|mcg|ml))/i.test(l)){let med=l.match(/\b([A-Z][a-zA-Z-]{3,}(?:\s[A-Z][a-zA-Z-]{3,})?)\b/);if(med&& !/(date|doctor|patient|report|hospital|clinic|glucose|cholesterol|hemoglobin|creatinine|test|tablet)/i.test(med[1]))medicines.push({name:med[1],dosage:l.trim()})}let diagnoses=[...new Set((text.match(/(?:diagnosis|impression|assessment)\s*:\s*([^\n.]+)/ig)||[]).map(x=>x.split(':').slice(1).join(':').trim()).filter(Boolean))];let doct=(text.match(/(?:doctor|dr\.)\s*:?\s*(Dr\.?\s*[A-Z][A-Za-z .'-]{2,35})/i)||[])[1]||'';let hosp=(text.match(/(?:hospital|clinic)\s*:?\s*([A-Z][A-Za-z .'-]{2,40})/i)||[])[1]||'';return{id:crypto.randomUUID(),title:name.replace(/\.[^/.]+$/,''),type:typePick,date:dt,raw:text.slice(0,25000),values:parseValues(text),medicines:[...new Map(medicines.map(m=>[m.name,m])).values()],diagnoses,doctor:doct.trim(),hospital:hosp.trim()}}
function explain(v){return `Your report marks ${v.name} (${v.value} ${v.unit||''}) as outside its printed reference range ${v.range||''}. A flagged result alone does not diagnose a condition. Results vary with health history, medicines, and lab methods; ask your clinician to interpret it. General wellbeing: keep regular checkups and follow guidance from your own care team.`}
function makeSummary(d){return summarizeDocument(d,get().lang||'en')}
function showDoc(id){let d=docs().find(x=>x.id===id);if(!d)return;let abnormal=d.abnormal||d.values.filter(v=>v.abnormal);const docModal=modal(esc(d.title),`${esc(d.type)} Â· ${fmt(d.date)}${d.doctor?' Â· '+esc(d.doctor):''}${d.hospital?' Â· '+esc(d.hospital):''}`,`<div class="formrow"><label>Simple-language summary</label><div class="insight" style="white-space:pre-wrap;line-height:1.7">${esc(get().lang!=='en'?makeSummary(d):(d.summary||makeSummary(d)))}</div><button class="button small" data-speak-summary>${icon('volume')} Speak summary</button></div>${d.values.length?`<div class="formrow"><label>Extracted test results</label>${d.values.map(v=>`<div class="timeline-item"><div class="docbody"><b>${esc(v.name)} Â· ${esc(v.value)} ${esc(v.unit||'')}</b><span>Reference range: ${esc(v.range||'Not shown')}</span>${v.abnormal?`<p class="cardhint">${esc(explain(v))}</p>`:''}</div><span class="tag ${v.abnormal?'warn':''}">${v.abnormal?'Review':'Recorded'}</span></div>`).join('')}</div>`:''}${d.medicines?.length?`<div class="formrow"><label>Medicines detected</label>${d.medicines.map(x=>`<div class="insight"><b>${esc(x.name)}</b><p>${esc(x.dosage)}</p></div>`).join('')}</div>`:''}<div class="advisory">${icon('alert')} ${esc(abnormal.length?abnormal.map(explain).join(' '):'This summary is informational only. Verify all extracted details against the original record. Consult a healthcare professional for interpretation.')}</div>`,'Done',()=>{});setTimeout(()=>{let btn=$('[data-speak-summary]');if(btn)btn.onclick=()=>speak(d.summary)},0)}
function addFamily(){modal('Add a family profile','Create a distinct health record under your signed-in Google account.','<div class="formrow"><label>Display name</label><input class="field" id="familyName" placeholder="e.g. Mother, Jamie Patel" required></div><div class="formrow"><label>Relationship</label><select class="select" id="familyRelationship"><option>Family member</option><option>Father</option><option>Mother</option><option>Child</option><option>Spouse</option><option>Other</option></select></div><div class="advisory">'+icon('alert')+' Only add a profile for someone whose records you are authorized to manage.</div>','Create profile',w=>{let name=w.querySelector('#familyName').value.trim();if(!name){toast('Enter a profile name');return false}api('/api/profiles',{method:'POST',body:JSON.stringify({name,relationship:w.querySelector('#familyRelationship').value})}).then(r=>{let id=r.profile.id;users[id]={id,name:r.profile.name,email:get().email,relationship:r.profile.relationship,...fresh()};active=id;sessionStorage.setItem('hc_active',active);save();route();toast('Family health profile created')}).catch(e=>toast(e.message));return true})}
function addReminder(){const medicines=[...new Set(docs().flatMap(d=>d.medicines||[]).map(m=>m.name))];openReminderEditor({profileId:active,medicines,api,toast,onSaved:r=>{remindersData={profileId:active,reminders:[...(remindersData?.profileId===active?remindersData.reminders:[]),r]};route()}})}
function addMed(){modal('Add a medicine to profile','Enter exactly as written on your current prescription.','<div class="formrow"><label>Medicine name</label><input class="field" id="medName" placeholder="e.g. Cetirizine"></div><div class="formrow"><label>Strength and directions (optional)</label><input class="field" id="medDose" placeholder="Use only the prescribed directions"></div><div class="advisory">'+icon('alert')+' This list does not verify whether a medicine is appropriate or safe for you.</div>','Add medicine',w=>{let name=w.querySelector('#medName').value.trim();if(!name){toast('Enter a medicine name');return false}get().meds.push({name,dosage:w.querySelector('#medDose').value.trim()});save();visitPrepData=null;route();toast('Medicine added to profile');return true})}
function editProfile(){let u=get();modal('Edit personal profile','Update the display name for this health profile.','<div class="formrow"><label>Name</label><input class="field" id="editName" value="'+esc(u.name)+'"></div><div class="formrow"><label>Email</label><input class="field" id="editEmail" value="'+esc(u.email||'')+'" type="email"></div>','Save profile',w=>{let n=w.querySelector('#editName').value.trim();if(!n){toast('Name is required');return false}u.name=n;u.email=w.querySelector('#editEmail').value.trim();save();route();return true})}
function abhaModal(){modal('Mock ABHA ID link','Hackathon-only placeholder. This does not connect to ABDM or verify identity.','<div class="formrow"><label>Mock ABHA-style ID</label><input class="field" id="abhaId" placeholder="xx-xxxx-xxxx-xxxx" value="'+esc(get().abha||'')+'"></div><div class="advisory">'+icon('alert')+' Use a fictional value only. Real ABHA integration requires official authorization and a secure consent workflow.</div>',get().abha?'Update link':'Save mock link',w=>{get().abha=w.querySelector('#abhaId').value.trim();save();route();toast(get().abha?'Mock ID saved':'Mock ID cleared');return true})}
async function exportFhir(){try{const r=await fetch(`/api/profiles/${active}/export.fhir.json`,{credentials:'same-origin'});if(!r.ok)throw new Error((await r.json()).error||'Export failed');const blob=await r.blob(),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`healthcopilot-${active}-fhir.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('FHIR-style bundle downloaded')}catch(e){toast(e.message)}}
function download(data,name,mime){let a=document.createElement('a'),url=URL.createObjectURL(new Blob([data],{type:mime}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function interaction(){let known=[...new Set([...get().meds.map(m=>m.name),...docs().flatMap(d=>(d.medicines||[]).map(m=>m.name))])];return modal('Medicine combination check','This checks a short list of known interaction patterns. It cannot confirm that a combination is safe.','<div class="formrow"><label>Medicines and supplements (one per line)</label><textarea class="field" id="intMeds" placeholder="Enter each medicine or supplement">'+esc(known.join('\n'))+'</textarea></div><div class="advisory">'+icon('alert')+' No match does not mean a medicine combination is safe. Ask a pharmacist to check the complete list, including doses and supplements.</div><div id="interactionResults"></div>','Check list',w=>{let medicines=w.querySelector('#intMeds').value.split(/[\n,;]/).map(x=>x.trim()).filter(Boolean);api(`/api/profiles/${active}/interactions`,{method:'POST',body:JSON.stringify({medicines})}).then(r=>{const result=w.querySelector('#interactionResults');result.innerHTML=r.matches.length?r.matches.map(m=>`<div class="alert"><b>${esc(m.severity)}</b><p>${esc(m.message)}</p><a class="text-button" href="${esc(m.source)}" target="_blank" rel="noopener noreferrer">Source information â†—</a></div>`).join(''):'<div class="insight"><b>No known pattern matched</b><p>'+esc(r.disclaimer)+'</p></div>';result.insertAdjacentHTML('beforeend',`<div class="advisory">${icon('alert')} ${esc(r.disclaimer)}</div>`)}).catch(e=>toast(e.message));return false})}
async function browserSpeak(text, wrap, button){if(!('speechSynthesis' in window)){toast('Speech playback is not supported in this browser.');return false}speechSynthesis.cancel();if(voiceAudio){voiceAudio.pause();voiceAudio=null}const lang=get().lang||'en', locale={en:'en-IN',hi:'hi-IN',te:'te-IN',ta:'ta-IN',kn:'kn-IN',ml:'ml-IN'}[lang]||'en-IN';let voices=speechSynthesis.getVoices();if(!voices.length)await new Promise(resolve=>{const timer=setTimeout(resolve,700);speechSynthesis.addEventListener('voiceschanged',()=>{clearTimeout(timer);resolve()},{once:true})});voices=speechSynthesis.getVoices();const voice=voices.find(v=>v.lang?.toLowerCase()===locale.toLowerCase())||voices.find(v=>v.lang?.toLowerCase().startsWith(locale.slice(0,2).toLowerCase()+'-'));if(!voice){toast(`No ${locale} speech voice is installed. Install that language voice in your device settings and reload.`);return false}const utterance=new SpeechSynthesisUtterance(String(text).slice(0,3500));utterance.voice=voice;utterance.lang=locale;utterance.onstart=()=>{if(button)button.textContent='Pause answer'};utterance.onend=()=>{if(button)button.textContent='Play answer'};utterance.onerror=()=>{if(button)button.textContent='Play answer';toast('Browser speech playback failed. Try another installed voice.')};speechSynthesis.speak(utterance);const controls=wrap?.querySelector('#voicePlayback');if(controls){controls.innerHTML='<button class="button small" data-speech-pause>Pause</button> <button class="button small" data-speech-resume>Resume</button> <button class="button small" data-speech-stop>Stop</button>';controls.querySelector('[data-speech-pause]').onclick=()=>speechSynthesis.pause();controls.querySelector('[data-speech-resume]').onclick=()=>speechSynthesis.resume();controls.querySelector('[data-speech-stop]').onclick=()=>{speechSynthesis.cancel();if(button)button.textContent='Play answer'}}return true}
async function speak(text){if(!text)return;try{const res=await fetch('/api/profiles/'+active+'/voice/speech',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({text:String(text).slice(0,3500),language:get().lang||'en'})});if(!res.ok){const d=await res.json().catch(()=>({}));if(d.browserSpeech){browserSpeak(text);return}throw new Error(d.error||'Spoken text could not be generated.')}if(voiceAudio){voiceAudio.pause();voiceAudio=null}if(voiceAudioUrl)URL.revokeObjectURL(voiceAudioUrl);voiceAudioUrl=URL.createObjectURL(await res.blob());voiceAudio=new Audio(voiceAudioUrl);voiceAudio.onplay=()=>{const b=document.querySelector('#universalVoiceToggle');if(b)b.textContent='Pause'};voiceAudio.onpause=()=>{const b=document.querySelector('#universalVoiceToggle');if(b)b.textContent=voiceAudio?.ended?'Play':'Resume'};voiceAudio.onended=()=>document.querySelector('#universalVoiceToggle')&&(document.querySelector('#universalVoiceToggle').textContent='Play');let bar=document.querySelector('#universalVoiceControls');if(!bar){bar=document.createElement('div');bar.id='universalVoiceControls';bar.className='voice-controls';bar.innerHTML='<span>Audio playback</span><button class="button small" id="universalVoiceToggle">Pause</button><button class="button small" id="universalVoiceStop">Stop</button>';document.body.append(bar);bar.querySelector('#universalVoiceToggle').onclick=()=>voiceAudio?.paused?voiceAudio?.play():voiceAudio?.pause();bar.querySelector('#universalVoiceStop').onclick=()=>{voiceAudio?.pause();speechSynthesis.cancel();if(voiceAudio)voiceAudio.currentTime=0;bar.remove()}}await voiceAudio.play()}catch(e){toast(e.message)}}
let voiceRecorder=null,voiceChunks=[],voiceAudio=null,voiceAudioUrl='';
function openVoiceMode(){if(!get().allowExternalAI){view='Settings';route();toast('Enable AI health agent consent in Settings to use multilingual voice.');return}document.querySelector('.voice-modal')?.remove();const wrap=document.createElement('div');wrap.className='modal-back voice-modal';wrap.innerHTML='<div class="modal voice-dialog"><h2>Talk with HealthCopilot</h2><p>Ask a question in '+esc(HEALTH_LANGUAGES.find(x=>x.code===get().lang)?.name||'English')+'. Your voice is transcribed for this conversation; audio is not saved by this app.</p><div class="advisory">HealthCopilot is an AI health information assistant, not a doctor. For emergencies, contact local emergency services.</div><div class="formrow"><label>Your question</label><div class="insight" id="voiceQuestion">Press Record and speak naturally.</div></div><div class="formrow"><label>HealthCopilot response</label><div class="insight" id="voiceAnswer">Your answer will appear here.</div></div><div class="modalfoot"><button class="button" data-vclose>Close</button><button class="button" data-vstop disabled>Stop</button><button class="button primary" data-vrecord>Record question</button><button class="button" data-vplay disabled>Play answer</button></div><div class="voice-playback" id="voicePlayback"></div></div>';document.body.append(wrap);wrap.querySelector('[data-vclose]').onclick=()=>{if(voiceRecorder?.state==='recording')voiceRecorder.stop();wrap.remove()};wrap.onclick=e=>{if(e.target===wrap){if(voiceRecorder?.state==='recording')voiceRecorder.stop();wrap.remove()}};wrap.querySelector('[data-vrecord]').onclick=()=>startVoiceRecording(wrap);wrap.querySelector('[data-vstop]').onclick=()=>{if(voiceRecorder?.state==='recording')voiceRecorder.stop()};wrap.querySelector('[data-vplay]').onclick=()=>toggleVoicePlayback(wrap.querySelector('[data-vplay]'))}
async function startVoiceRecording(wrap) {
    if (!navigator.mediaDevices?.getUserMedia || !window.MediaRecorder) {
        toast('Audio recording is unavailable in this browser. Use a current Chrome or Edge browser over localhost or HTTPS.');
        return;
    }
    const recordButton = wrap.querySelector('[data-vrecord]');
    const stopButton = wrap.querySelector('[data-vstop]');
    if (recordButton.disabled) return;
    recordButton.disabled = true;
    let stream;
    try {
        stream = await navigator.mediaDevices.getUserMedia({ audio: true });
        if (!wrap.isConnected) {
            stream.getTracks().forEach((track) => track.stop());
            return;
        }
        const mime = ['audio/webm;codecs=opus', 'audio/webm', 'audio/mp4'].find((type) => MediaRecorder.isTypeSupported(type));
        const recorder = new MediaRecorder(stream, mime ? { mimeType: mime } : {});
        const chunks = [];
        voiceRecorder = recorder;
        recorder.ondataavailable = (event) => { if (event.data.size) chunks.push(event.data); };
        recorder.onstop = async () => {
            stream.getTracks().forEach((track) => track.stop());
            if (!wrap.isConnected) return;
            const blob = new Blob(chunks, { type: recorder.mimeType || 'audio/webm' });
            stopButton.disabled = true;
            wrap.querySelector('#voiceQuestion').textContent = 'Transcribing your question...';
            try {
                const form = new FormData();
                form.append('audio', blob, `question.${blob.type.includes('mp4') ? 'mp4' : 'webm'}`);
                                form.append('language', get().lang || 'en');
                const response = await fetch(`/api/profiles/${active}/voice/transcribe`, { method: 'POST', credentials: 'same-origin', body: form });
                const data = await response.json();
                if (!wrap.isConnected) return;
                if (!response.ok) throw new Error(data.error || 'Transcription failed.');
                const question = data.text;
                wrap.querySelector('#voiceQuestion').textContent = question;
                wrap.querySelector('#voiceAnswer').textContent = 'Preparing a clear answer from your records and general health information...';
                const answer = await ask(question);
                async function speak(text){if(!text)return;try{const res=await fetch('/api/profiles/'+active+'/voice/speech',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({text:String(text).slice(0,3500),language:get().lang||'en'})});if(!res.ok){const d=await res.json().catch(()=>({}));throw new Error(d.error||'Spoken text could not be generated.')}if(voiceAudio){voiceAudio.pause();voiceAudio=null}if(voiceAudioUrl)URL.revokeObjectURL(voiceAudioUrl);voiceAudioUrl=URL.createObjectURL(await res.blob());voiceAudio=new Audio(voiceAudioUrl);voiceAudio.onplay=()=>{const b=document.querySelector('#universalVoiceToggle');if(b)b.textContent='Pause'};voiceAudio.onpause=()=>{const b=document.querySelector('#universalVoiceToggle');if(b)b.textContent=voiceAudio?.ended?'Play':'Resume'};voiceAudio.onended=()=>document.querySelector('#universalVoiceToggle')&&(document.querySelector('#universalVoiceToggle').textContent='Play');let bar=document.querySelector('#universalVoiceControls');if(!bar){bar=document.createElement('div');bar.id='universalVoiceControls';bar.className='voice-controls';bar.innerHTML='<span>Audio playback</span><button class="button small" id="universalVoiceToggle">Pause</button><button class="button small" id="universalVoiceStop">Stop</button>';document.body.append(bar);bar.querySelector('#universalVoiceToggle').onclick=()=>voiceAudio?.paused?voiceAudio?.play():voiceAudio?.pause();bar.querySelector('#universalVoiceStop').onclick=()=>{voiceAudio?.pause();if(voiceAudio)voiceAudio.currentTime=0;bar.remove()}}await voiceAudio.play()}catch(e){toast(e.message)}}
                if (!wrap.isConnected) return;
                if (!answer) throw new Error('HealthCopilot could not prepare an answer.');
                wrap.querySelector('#voiceAnswer').textContent = answer;
                wrap.querySelector('[data-vplay]').disabled = false;
                await loadVoiceAudio(answer, wrap);
            } catch (error) {
                if (wrap.isConnected) wrap.querySelector('#voiceAnswer').textContent = error.message;
                toast(error.message);
            } finally {
                if (wrap.isConnected) recordButton.disabled = false;
            }
        };
        recorder.start();
        stopButton.disabled = false;
        wrap.querySelector('#voiceQuestion').textContent = 'Listening. Speak your question, then press Stop.';
    } catch (error) {
        stream?.getTracks().forEach((track) => track.stop());
        recordButton.disabled = false;
        stopButton.disabled = true;
        toast(error.name === 'NotAllowedError' ? 'Microphone access is blocked. Allow microphone access in your browser settings.' : `Could not start microphone: ${error.message}`);
    }
}
async function loadVoiceAudio(text,wrap){const res=await fetch('/api/profiles/'+active+'/voice/speech',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({text,language:get().lang||'en'})});if(!res.ok){const data=await res.json().catch(()=>({}));if(data.browserSpeech){browserSpeak(text,wrap,wrap.querySelector('[data-vplay]'));return}throw new Error(data.error||'Spoken answer could not be generated.');}if(voiceAudio){voiceAudio.pause();voiceAudio=null}if(voiceAudioUrl)URL.revokeObjectURL(voiceAudioUrl);voiceAudioUrl=URL.createObjectURL(await res.blob());voiceAudio=new Audio(voiceAudioUrl);voiceAudio.onplay=()=>{const b=wrap.querySelector('[data-vplay]');if(b)b.textContent='Pause answer'};voiceAudio.onpause=()=>{const b=wrap.querySelector('[data-vplay]');if(b)b.textContent=voiceAudio?.ended?'Play answer':'Resume answer'};voiceAudio.onended=()=>{const b=wrap.querySelector('[data-vplay]');if(b)b.textContent='Play answer'};const el=wrap.querySelector('#voicePlayback');el.innerHTML='<button class="button small" data-vpause>Pause audio</button> <button class="button small" data-vresume>Resume audio</button> <button class="button small" data-vstopaudio>Stop audio</button>';el.querySelector('[data-vpause]').onclick=()=>voiceAudio?.pause();el.querySelector('[data-vresume]').onclick=()=>voiceAudio?.play();el.querySelector('[data-vstopaudio]').onclick=()=>{voiceAudio?.pause();if(voiceAudio)voiceAudio.currentTime=0;const b=wrap.querySelector('[data-vplay]');if(b)b.textContent='Play answer'};await voiceAudio.play()}
function toggleVoicePlayback(button){if('speechSynthesis'in window&&speechSynthesis.speaking){if(speechSynthesis.paused){speechSynthesis.resume();if(button)button.textContent='Pause answer'}else{speechSynthesis.pause();if(button)button.textContent='Resume answer'}return}if(!voiceAudio)return;if(voiceAudio.paused){voiceAudio.play().catch(e=>toast('Audio playback failed: '+e.message))}else voiceAudio.pause()}
async function speakAnswer(text,button){try{if(('speechSynthesis'in window)&&speechSynthesis.speaking){if(speechSynthesis.paused)speechSynthesis.resume();else speechSynthesis.pause();return}if(voiceAudio&&!voiceAudio.paused){voiceAudio.pause();return}const res=await fetch('/api/profiles/'+active+'/voice/speech',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({text,language:get().lang||'en'})});if(!res.ok){const d=await res.json().catch(()=>({}));if(d.browserSpeech){browserSpeak(text,null,button);return}throw new Error(d.error||'Spoken answer could not be generated.')}if(voiceAudioUrl)URL.revokeObjectURL(voiceAudioUrl);voiceAudioUrl=URL.createObjectURL(await res.blob());voiceAudio=new Audio(voiceAudioUrl);voiceAudio.onplay=()=>button.textContent='Pause answer';voiceAudio.onpause=()=>button.textContent='Play answer';voiceAudio.onended=()=>button.textContent='Play answer';await voiceAudio.play()}catch(e){toast(e.message)}}
function voiceInput(){openVoiceMode()}
function answer(q){let ds=docs(),lab=allLabs(),lower=q.toLowerCase();if(!ds.length)return 'There are no records in this profile yet. Upload a report  I only search this profile.';if(/highest|maximum|most/.test(lower)&&/(bp|blood pressure)/.test(lower)){let b=lab.filter(x=>/bp|systolic|diastolic/i.test(x.name));return b.length?'Highest recorded matching result: '+b.sort((x,y)=>Number(y.value)-Number(x.value))[0].name+' was '+b.sort((x,y)=>Number(y.value)-Number(x.value))[0].value+' '+(b[0].unit||'')+' on '+fmt(b[0].date)+'. Check the original report for context.':'I could not find a blood pressure measurement in this profile.'}if(/sugar|glucose|hba1c|a1c/.test(lower)){let b=lab.filter(x=>/glucose|sugar|hba1c|a1c/i.test(x.name)).sort((a,b)=>new Date(b.date)-new Date(a.date));return b.length?'Your matching results: '+b.map(x=>`${x.name} ${x.value} ${x.unit||''} (${fmt(x.date)}${x.abnormal?', flagged against the report range':''})`).join('; ')+'. Please discuss these with your clinician; reference ranges and clinical meaning depend on context.':'No glucose or A1c result was found in this profile.'}if(/antibiotic/.test(lower)){let meds=ds.flatMap(d=>(d.medicines||[]).filter(m=>/cillin|mycin|cycline|floxacin|ceph|sulfa|antibiotic/i.test(m.name)).map(m=>({name:m.name,date:d.date})));return meds.length?'The most recent matching medicine in your uploaded records is '+meds.sort((a,b)=>new Date(b.date)-new Date(a.date))[0].name+' ('+fmt(meds[0].date)+'). This only reflects documents you uploaded.':'I did not find an antibiotic name in the records I can access.'}if(/medicine|medication|drug|prescription/.test(lower)){let meds=ds.flatMap(d=>(d.medicines||[]).map(m=>`${m.name}${m.dosage?' â€” '+m.dosage:''} (${fmt(d.date)})`));return meds.length?'Medicines identified in your uploaded records: '+[...new Set(meds)].join('; ')+'. Verify with your current prescription.':'I did not find medicine details in your uploaded records.'}if(/last|latest|recent/.test(lower)&&/report|document|visit|test/.test(lower))return `Your latest uploaded record is ${ds[0].title} (${fmt(ds[0].date)}).`+ (ds[0].summary?` Summary: ${ds[0].summary.split('\n')[0]}`:'');if(/abnormal|flag|outside|high|low|result/.test(lower)){let a=ds.flatMap(d=>(d.values||[]).filter(v=>v.abnormal).map(v=>({...v,date:d.date})));return a.length?'Your reports flag these values for review: '+a.map(x=>`${x.name} ${x.value} ${x.unit||''} (reference ${x.range||'not shown'}, ${fmt(x.date)})`).join('; ')+'. A flag is not a diagnosis. Ask your healthcare professional to interpret it.':'No values are marked outside a printed range in the extracted reports I can see.'}if(/doctor|hospital/.test(lower)){let arr=ds.filter(d=>d.doctor||d.hospital).map(d=>`${d.doctor||''} ${d.hospital?'at '+d.hospital:''} (${fmt(d.date)})`);return arr.length?'Provider details found in records: '+arr.join('; ')+'. Verify against your original documents.':'No doctor or hospital names were confidently extracted.'}return `I searched ${ds.length} document${ds.length===1?'':'s'} in the active profile. I can retrieve recorded glucose/A1c results, medicines, provider names, flagged values, and recent report dates. I could not reliably answer that question from the stored records. Try a more specific question or check the original document. This is not medical advice.`}
async function ask(q){q=q?.trim();if(!q)return '';const u=get();u.messages.push({role:'user',text:q},{role:'assistant',text:'Checking your profile...'});route();try{const i=u.messages.length-1,r=await api(`/api/profiles/${active}/chat`,{method:'POST',body:JSON.stringify({question:q,language:u.lang||'en',history:u.messages.slice(0,-2).slice(-8),allowExternalAI:!!u.allowExternalAI})});u.messages[i].text=r.answer;save();route();let box=$('#chatbox');if(box)box.scrollTop=box.scrollHeight;return u.messages[i].text}catch(e){u.messages.pop();if(u.messages.at(-1)?.role==='user')u.messages.pop();toast(`Health Agent could not answer: ${e.message}`);route();return ''}}
function exportReport(){let u=get(),ds=docs();if(!ds.length){toast('Add records before exporting a report.');return}let html=`<!doctype html><html><head><meta charset="utf-8"><title>Health summary Â· ${esc(u.name)}</title><style>body{font:14px Arial,sans-serif;color:#203536;max-width:760px;margin:40px auto;padding:0 22px}h1{font-size:25px}h2{font-size:17px;margin-top:25px}.muted{color:#71817e;font-size:12px}.block{border:1px solid #dde6e0;padding:14px;margin:12px 0;border-radius:8px}.warning{color:#aa5548}.legal{background:#f3f6f4;padding:12px;font-size:11px;color:#65766c;margin-top:22px}@media print{button{display:none}body{margin:12mm auto}}</style></head><body><button id="print-report">Print / Save as PDF</button><h1>Personal health summary</h1><p>${esc(u.name)} Â· Prepared ${fmt(today())} Â· Selected period: all uploaded records</p>${ds.map(d=>`<div class="block"><h2>${esc(d.title)}</h2><p class="muted">${esc(d.type)} Â· ${fmt(d.date)}</p><p>${esc(get().lang!=='en'?makeSummary(d):(d.summary||makeSummary(d))).replace(/\n/g,'<br>')}</p>${d.values?.map(v=>`<p class="${v.abnormal?'warning':''}">${esc(v.name)}: ${esc(v.value)} ${esc(v.unit||'')} ${v.range?'(reference '+esc(v.range)+')':''} ${v.abnormal?'â€” flagged for review':''}</p>`).join('')||''}</div>`).join('')}<div class="legal">Medical disclaimer: This report was generated from information provided by the user. It may contain errors and does not diagnose, treat, or replace professional medical advice. Verify details against original documents and consult your healthcare professional.</div></body></html>`;let w=window.open('','_blank');if(!w){toast('Allow pop-ups to print your PDF report');return}w.document.write(html);w.document.close();setTimeout(()=>w.print(),350)}
function bindFinal(){document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;route()});$('#switchProfile')?.addEventListener('change',e=>{speechSynthesis?.cancel?.();voiceAudio?.pause();active=e.target.value;save();route()});$('#searchDocs')?.addEventListener('input',e=>{filter=e.target.value;let at=e.target.selectionStart;route();let inp=$('#searchDocs');inp?.focus();inp?.setSelectionRange(at,at)});$('#typeFilter')?.addEventListener('change',e=>{typeFilter=e.target.value;route()});$('#dateFilter')?.addEventListener('change',e=>{dateFilter=e.target.value;route()});$('#chartKey')?.addEventListener('change',e=>{window.chartKey=e.target.value;route()});$('#langSelect')?.addEventListener('change',e=>{get().lang=e.target.value;save();toast(e.target.value==='hi'?'Hindi preference saved.':'Language preference saved.')});$('#chatform')?.addEventListener('submit',e=>{e.preventDefault();ask($('#chatinput').value)});document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action,b));let zone=$('.uploadzone');if(zone){zone.ondragover=e=>{e.preventDefault();zone.classList.add('drag')};zone.ondragleave=()=>zone.classList.remove('drag');zone.ondrop=e=>{e.preventDefault();zone.classList.remove('drag');processFiles([...e.dataTransfer.files])}}}
function quotaInfo(){return '<div class="card"><div class="cardtitle">AI provider and usage limits</div><p class="cardhint">This deployment uses the server-side provider configured by AI_PROVIDER. API limits vary by account, model, and region; a 429 response means the provider limit was reached. Keep provider keys on the server and use synthetic records for hackathon demonstrations.</p><div class="maternal-resource"><a href="https://console.groq.com/settings/limits" target="_blank" rel="noopener noreferrer">View Groq usage and limits</a><span>Check model access, request limits, and usage in Groq Console.</span></div><div class="maternal-resource"><a href="https://console.groq.com/keys" target="_blank" rel="noopener noreferrer">Manage Groq API keys</a><span>Keep keys in server environment variables only.</span></div><div class="maternal-resource"><a href="https://console.groq.com/docs/text-to-speech" target="_blank" rel="noopener noreferrer">Speech options and model pricing</a><span>Groq TTS is not used by this free configuration; browser voices are used for spoken answers.</span></div></div>'}
const renderOriginal=route;route=function(){if(!authState?.authenticated){renderLogin();return}renderOriginal();localizeTree($('#app'),get().lang);if(view==='Settings')$('#app .page')?.insertAdjacentHTML('beforeend',quotaInfo());if(view==='Documents'){let h=$('.pagehead');if(h&&!$('[data-action="export"]')){let b=document.createElement('button');b.className='button';b.dataset.action='export';b.innerHTML=icon('download')+' PDF summary';h.querySelector('.button.primary').before(b);b.onclick=exportReport}}if(view==='Maternal Care')bindMaternalCare($('.maternal-care'),{maternal:get().maternal||{},language:get().lang||'en',toast,onSave:async maternal=>{get().maternal=maternal;const saved=await save(true);if(saved)route();return saved}});bindExtra()};
function bindExtra(){document.querySelectorAll('[data-speak-summary]').forEach(b=>b.addEventListener('click',()=>speak(b.closest('.modal').dataset.summary||'')))}
document.addEventListener('click', async event => {
    const button = event.target.closest('[data-dose-log]');
    if (!button || button.disabled) return;
    button.disabled = true;
    const { reminderId, doseDate, doseStatus } = button.dataset;
    const u = get();
    const next = (u.doseLogs || []).filter(entry => entry.reminderId !== reminderId || entry.date !== doseDate);
    next.push({ reminderId, date: doseDate, status: doseStatus, markedAt: new Date().toISOString() });
    u.doseLogs = next.slice(-500);
    if (await save(true)) {
        route();
        toast(doseStatus === 'taken' ? 'Dose marked taken for today.' : 'Dose recorded as missed. Follow your prescription; do not double a dose.');
    } else button.disabled = false;
});
function renderLogin(error=''){const configured=!!authState?.googleConfigured;$('#app').innerHTML=`<main class="login-page"><div class="login-card"><div class="brand login-brand"><div class="brandmark">${icon('logo')}</div><span>health<span style="color:#3c805e">copilot</span></span></div><div class="eyebrow">YOUR PRIVATE HEALTH WORKSPACE</div><h1>Understand your health records.</h1><p class="login-copy">Keep your reports together, get plain-language summaries, and prepare for conversations with your care team.</p>${error?`<div class="alert"><b>Sign-in could not complete</b><p>${esc(error)}</p></div>`:''}<a class="button primary google-button ${configured?'':'disabled'}" href="${configured?'/auth/google':'#oauth-setup'}" ${configured?'':'aria-disabled="true"'}><span class="google-g">G</span> Continue with Google</a>${!configured?'<div class="setup-note" id="oauth-setup">Google sign-in is not configured yet. Set GOOGLE_CLIENT_ID, GOOGLE_CLIENT_SECRET, and DATABASE_URL in your local .env file, then restart the server.</div>':''}${authState?.developmentMode?'<a class="button" style="display:block;margin-top:12px;text-align:center" href="/auth/demo">Open local feature walkthrough</a><div class="setup-note">Development only: local synthetic account, no Google login. Disabled in production.</div>':''}<div class="privacy-note">${icon('shield')} Your records are encrypted and linked to your account. Only your account can access its family profiles.</div><div class="medical-note">HealthCopilot organizes information. It does not diagnose or replace professional medical care.</div></div></main>`}
async function bootstrap(){try{authState=await api('/api/me');if(!authState.authenticated){renderLogin(location.search.includes('auth=failed')?'Google sign-in failed. Check the OAuth redirect URI and try again.':'');return}const {profiles}=await api('/api/profiles');users={};for(const p of profiles){const data=await api(`/api/profiles/${p.id}/workspace`);users[p.id]={id:p.id,name:data.profile.name,email:data.profile.email,relationship:data.profile.relationship,dateOfBirth:data.profile.date_of_birth,abha:data.profile.abha_mock_id||'',...fresh(),...data.state,docs:data.docs}}if(!Object.keys(users).length){await api('/auth/logout',{method:'POST'});authState={authenticated:false,googleConfigured:authState.googleConfigured};renderLogin('No health profile was available for this account. Please sign in again.');return}if(!users[active])active=Object.keys(users).find(id=>users[id].relationship==='Self')||Object.keys(users)[0];sessionStorage.setItem('hc_active',active);route()}catch(e){console.error(e);authState={authenticated:false,googleConfigured:false};const dbError=/database|postgres|connect|ECONN|socket|pg_hba|password authentication|timeout/i.test(e.message);$('#app').innerHTML=`<main class="login-page"><div class="login-card"><div class="brand login-brand">${icon('logo')} health<span style="color:#3c805e">copilot</span></div><h1>HealthCopilot needs setup.</h1><p class="login-copy">${esc(e.message)}${dbError?'. Start PostgreSQL, set the real DATABASE_URL in .env, then run npm run db:setup.':''}</p><button class="button" data-retry-server>Retry connection</button></div></main>`;$('#app [data-retry-server]')?.addEventListener('click',()=>location.reload())}}
route();bootstrap();

